import st,numpy as np
def inv(n,pts,z=None):
    z=st.CFG[n][2] if z is None else z;Hi=np.linalg.inv(np.array(st.H(n)).reshape(3,3));o=[]
    for (x,y) in pts:
        v=Hi@np.array([x,y+z,1.0]);o.append('(%.1f,%.1f)'%(v[0]/v[2],v[1]/v[2]))
    return ' '.join(o)
